import { createClient } from '@supabase/supabase-js';

// ─── Read credentials from environment ───────────────────────────────────────
const supabaseUrl = process.env.REACT_APP_SUPABASE_URL;
const supabaseAnonKey = process.env.REACT_APP_SUPABASE_ANON_KEY;

// ─── Debug: log what React sees at startup ────────────────────────────────────
if (process.env.NODE_ENV === 'development') {
  console.log('[Supabase] URL found:', !!supabaseUrl);
  console.log('[Supabase] Key found:', !!supabaseAnonKey);
}

// ─── Validate ─────────────────────────────────────────────────────────────────
if (!supabaseUrl || !supabaseAnonKey) {
  console.error(
    '❌ MISSING Supabase credentials!\n' +
    'Make sure client/.env contains:\n' +
    '  REACT_APP_SUPABASE_URL=https://xxxx.supabase.co\n' +
    '  REACT_APP_SUPABASE_ANON_KEY=eyJ...\n\n' +
    '⚠️  You MUST restart the dev server after editing .env (Ctrl+C then npm start)'
  );
}

// ─── Create client (always — even if env is missing, so the app loads) ────────
//     If credentials are missing, Supabase calls will fail with a clear network
//     error rather than a silent null-check failure.
export const supabase =
  supabaseUrl && supabaseAnonKey
    ? createClient(supabaseUrl, supabaseAnonKey)
    : null;

// ─── Helper: call this at the top of any auth action ─────────────────────────
export function assertSupabase() {
  if (!supabase) {
    throw new Error(
      'Supabase is not configured. ' +
      'Check that REACT_APP_SUPABASE_URL and REACT_APP_SUPABASE_ANON_KEY ' +
      'are set in client/.env and that you restarted the dev server.'
    );
  }
  return supabase;
}
